insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('3da3c977-1c1a-4ca4-8aa6-4e5146460df7', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'blue-safari-submarine-subscooter', 'activity'::activity_type, 'Blue Safari Submarine & Subscooter', 'Descend into the depths of the Indian Ocean by submarine or subscooter to explore reefs, corals, marine life and the wreck of ''Le Star Hope''.', 'Gradually discover the underwater world by observing the beauty of the Indian Ocean and its marine life. You will receive a briefing before boarding the submarine from a boat platform. As you descend into the depths, you will explore the reefs, the corals, the local marine wildlife, the wreck of ''Le Star Hope,'' and an ancient anchor from the 17th century at the bottom of the ocean.', 'Sea & water activities', 'Trou Aux Biches Costal Road', '75', 'Trou Aux Biches Costal Road', 't', '{English,French}'::text[], '{"Briefing before boarding","Pick-up and drop-off at all parts of the island"}'::text[], '{"Do not drink if you are going to drive","Arrive at the boarding point at least 15 minutes before the cruise start time"}'::text[], '{"Explore the reefs and corals","Observe local marine wildlife","See the wreck of ''Le Star Hope''","Discover an ancient 17th-century anchor at the bottom of the ocean"}'::text[], 'Full Refund up to 24 Hours', 'published'::activity_status, NULL, NULL, NULL, '0', '2026-06-19 20:14:04.421184+00', '{"startWindow": "09:00"}'::jsonb, '10', 'per_person', 'f', 'North', '-20.031', '57.553', '1', 'f', 'f', '1', NULL, NULL, NULL);
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('2d78f6bf-902a-4296-ade4-5fa52a67cc65', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'casela-world-of-adventures', 'activity'::activity_type, 'Casela World of Adventures', 'Day trip to Casela World of Adventures, a 14-hectare nature and leisure park with safaris, zip lines, walking with lions and family activities.', 'Welcome to the adventure world of Casela. Join us for an unforgettable day filled with activities for the whole family! 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('9962c783-f94a-41b3-bc9f-db2980aefe6b', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'catamaran-cruise-3-northern-island-adventure', 'activity'::activity_type, 'Catamaran Cruise 3 Northern Island Adventure', 'A full day from Grand Baie exploring Île Plate with lagoon snorkeling, a gourmet lunch on board, relaxation at Île aux Gabriel, and sunset views of Coin de Mire.', 'Depart from Grand Baie for a full day exploring Île Plate. Enjoy crystal-clear lagoon snorkeling with incredible fish and coral varieties. A gourmet lunch is prepared on the spacious catamaran, followed by relaxation at Île aux Gabriel. The day concludes with sunset views of Coin de Mire''s spectacular cliffs.', 'Catamaran cruises', 'Grand Baie, Sunset Boulevard', '480', 'Grand Baie', 't', '{English,French}'::text[], '{"Lunch with salads","Garlic butter bread","Grilled chicken/fish/sausage","Water, Coke, beer, wine, local rum","Flaming banana","Fruit salads",Snorkeling}'::text[], '{"Do not drink if you are going to drive","Arrive 15 minutes before departure","Own transport users must find directions on Google Maps"}'::text[], '{"Île Plate (Northern Region)","Ile Aux Gabriel (Northern Region)","Coin de Mire (Northern Region)","Snorkeling (Northern Region)"}'::text[], 'Full refund up to 24 hours', 'published'::activity_status, NULL, NULL, NULL, '0', '2026-06-19 20:14:04.421184+00', '{"itinerary": [{"area": null, "tags": [], "title": "Grand Baie, Sunset Boulevard", "description": "Departure"}, {"area": null, "tags": [], "title": "Gabriel Island", "description": "Visit"}, {"area": null, "tags": [], "title": "Flat Island", "description": null}, {"area": null, "tags": [], "title": "Gunner''s Quoin", "description": "Snorkeling"}]}'::jsonb, '10', 'per_person', 'f', 'North', '-20.0104', '57.5789', '2', 'f', 'f', '1', NULL, NULL, NULL);
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('59d694e1-e076-4cec-b761-b462687e26a0', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'catamaran-cruise-ile-aux-cerfs', 'activity'::activity_type, 'Catamaran Cruise – Ile Aux Cerfs', 'A full-day catamaran cruise from Trou D''eau Douce visiting the Grand River South East Waterfall, snorkeling, a BBQ lunch on board, and Ile aux Cerfs.', 'Enjoy a full-day catamaran cruise departing from Trou D''eau Douce on Mauritius''s east coast. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('177e8323-a359-4233-852a-c3a7ae083759', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'catamaran-sunset-cruise', 'activity'::activity_type, 'Catamaran Sunset Cruise', 'Sail peacefully through the stunning sunset over Grand Bay on a beautiful catamaran while relaxing with a refreshing cocktail.', 'Sail peacefully through the stunning sunset over Grand Bay on a beautiful catamaran while relaxing with a refreshing cocktail. The sunsets on the northwest coast of Mauritius are legendary, and the best way to experience them is from the ocean. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('4ffb45b2-365d-4884-afbc-84aca75de00f', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'catapseed-5-islands', 'activity'::activity_type, 'Private Cataspeed 5 Islands', 'Discover the stunning east coast of Mauritius with visits to the Grand River South East Waterfall, five beautiful islands, and incredible snorkeling in crystal-clear lagoons. Enjoy breathtaking scenery, spot vibrant marine life, and relax on an unforgettable CataSpeed cruise.', 'Your full-day cruise begins at the public jetty in Trou d''Eau Douce, where you''ll meet the crew before setting off to discover the stunning east coast of Mauritius. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('4c1ec0a9-00ce-49d6-8554-da65bf3a74c6', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'custom-road-trip', 'activity'::activity_type, 'Custom Road Trip', 'Design your own day across Mauritius with the AI planner — one flat price per vehicle.', NULL, 'Taxi Sightseeing tours', NULL, '480', NULL, 't', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], NULL, 'published'::activity_status, NULL, NULL, NULL, '0', '2026-06-17 22:31:27.128993+00', '{}'::jsonb, '10', 'vehicle_custom', 't', NULL, NULL, NULL, '1', 'f', 'f', '12', NULL, NULL, NULL);
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('268a885f-c018-452e-add8-9cf72ecc2f60', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'deep-sea-fishing', 'activity'::activity_type, 'Deep Sea fishing', 'Fish for Blue Marlin, Dorado and other big game under the guidance of experienced skippers on well-equipped modern boats.', 'Whether you are a beginner or an expert, you will enjoy fishing for a Blue Marlin, a Dorado, or other large fish under the guidance of experienced skippers. The modern boats designed for deep-sea fishing are well equipped. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('56e84f5b-ac60-486c-8937-3aee22812365', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'encountering-the-whales-and-swim-with-dolphins-excursion', 'activity'::activity_type, 'Encountering the Whales and swim with Dolphins excursion', 'A West coast boat excursion to admire humpback or sperm whales and snorkel with dolphins, under the supervision of professional skippers and crew.', 'A unique experience creating memories to last for a lifetime! Immerse yourself in the adventure of a lifetime which will bring you into contact with strikingly beautiful scenery, unspoiled landscapes and wonderful marine animals. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('bfb6c5df-ccdc-4090-bd86-a1b7491c35b6', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'flat-island-gabriel-island-and-the-gunners-coin-by-speedboat-exclusive-basis-only', 'activity'::activity_type, 'Full Day 3 Northern Island Speed Boat with Lunch(BBQ)', 'A private speedboat day trip from Grand Bay to Flat Island, Gabriel Island and Gunner''s Coin, with snorkeling, BBQ lunch and beverages.', 'A private day trip by speedboat to visit three northern islands of Mauritius. Departure is from Grand Bay, with an approximately 45-minute journey to Flat Island for relaxation and snorkeling in the lagoons. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('419bcd80-9ba2-4cc8-adbe-db96d89831d2', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'helicotour', 'activity'::activity_type, 'Helicopter Tour of Mauritius', 'Discover Mauritius from above on a private helicopter flight departing from the Triolet base in the north, with three packages from a short scenic hop to a full island tour.', 'The must (departing from Triolet, North): A short flight and memories forever etched in your mind. The route departing from the Triolet base includes a flyover of the northern landscapes and islets. Enjoy the bustling life of Grand-Baie seen from above and the boats lined up near the golden sand beach. Then fly over Coin de Mire, which dominates the north coast, and Ile Plate, home to various species of reptiles. The flight ends with a magnificent stretch over Ile d''Ambre, where the famous Saint-Geran was shipwrecked and which was the setting of Paul et Virginie by Bernardin de Saint-Pierre.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('d4dcc848-ef41-4f8f-85db-14bbd3803a2c', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'hiking-at-the-tamarind-falls-7-cascade', 'activity'::activity_type, 'Hiking At The Tamarind Falls / 7 Cascade', 'Guided hike to Tamarind Falls (7 Cascades), the highest waterfall in Mauritius, through plateaus rich in plants and exotic birds.', '7 Cascades, also known as Tamarind Falls, is located near the small village of Henrietta, on the high plateaus of Mauritius, and its source originates from Rivière Tamarin. The 7 Cascades measure 293 meters/961 feet, making it the highest waterfall in Mauritius. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('4dc413ac-04ef-433b-b0c3-b93b224c6e05', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'hiking-le-morne', 'activity'::activity_type, 'Hiking Le Morne', 'Climb the UNESCO World Heritage Le Morne mountain to its ''V'' summit for spectacular views of turquoise lagoons and lush mountain ranges.', 'Discover the beauty and majesty of Morne Mountain as you climb from its base to the peak of the ''V'' summit while enjoying the spectacular landscape. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('67b2f533-d3c5-47cb-98cf-456c45f44130', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'horse-back-riding-on-the-beach', 'activity'::activity_type, 'Horse Back Riding on the Beach', 'Discover the perfect blend of adventure and relaxation with a guided horseback ride along the stunning beaches of Mauritius. At Belle Mare Beach, our beach rides let you take in the island''s breathtaking coastline while enjoying an unforgettable experience in nature.', 'Whether you''re an experienced rider or trying horseback riding for the first time, Belle Mare Tours offers guided beach rides designed to be safe, relaxing, and memorable. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('a23001d8-f1a1-407e-9ab3-7075f4ff14ac', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'la-vallee-des-couleurs-nature-park-2', 'activity'::activity_type, 'Vallée Adventure Park', 'Day trip to La Vallée des Couleurs nature park, with its 23-coloured earth, four waterfalls, native wildlife and flora in southern Mauritius.', 'Nature lovers will find this destination appealing, offering a unique experience with indigenous wildlife and flora. The park features diverse landscapes including plateaus, mountains, valleys, craters and crater lakes. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('2402ab1e-1695-4485-a120-561d08797854', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'north-beaches-tour', 'activity'::activity_type, 'Beach Hopping Tour (North Beaches)', 'An exclusive private beach-hopping day tour to five northern Mauritius beaches with complimentary beach chairs, umbrella, mat, snacks and drinks, and an English/French-speaking driver.', 'An exclusive private beach tour exploring five northern Mauritius beaches in a single day. Visitors are transported by dedicated chauffeur across Trou aux Biches, Mont Choisy, La Cuvette, Grand Bay, and Pereybere beaches. The experience includes complimentary beach chairs, umbrellas, mats, snacks, and refreshing drinks. Each beach offers distinct characteristics: Mont Choisy features crystal waters and marine life; Pereybere provides vibrant atmosphere with local cafes; Grand Bay offers water sports and shopping; Trou aux Biches delivers serene, family-friendly conditions; La Cuvette provides a secluded, tranquil escape. The driver assists with beach setup and provides English/French-speaking guidance throughout.', 'Taxi Sightseeing tours', 'North', '330', NULL, 't', '{English,French}'::text[], '{"Pickup and drop-off from any hotel/Airbnb in Mauritius","Private vehicle and transportation between beaches","English/French-speaking driver","Supermarket stop on route","One beach umbrella, two beach chairs, one beach mat (minimum)","Snacks and chilled soft drinks","First child seat (upon request)"}'::text[], '{"Lunch (though driver provides restaurant recommendations)","Entry tickets to visiting places","Additional beach chairs/umbrellas beyond specified amounts"}'::text[], '{"Trou aux Biches Beach","Mont Choisy Beach","La Cuvette Beach","Grand Bay Beach","Pereybere Beach"}'::text[], NULL, 'published'::activity_status, NULL, NULL, NULL, '0', '2026-06-19 20:14:04.421184+00', '{"itinerary": [{"area": "North Region", "tags": [], "title": "Grand Bay Beach", "description": null}, {"area": "North Region", "tags": [], "title": "Pereybere Beach", "description": null}, {"area": "North Region", "tags": [], "title": "Mont Choisy Beach", "description": null}, {"area": "North Region", "tags": [], "title": "Trou Aux Biches", "description": null}, {"area": "North Region", "tags": [], "title": "Cap Malheureux", "description": null}]}'::jsonb, '10', 'vehicle', 'f', NULL, '-20.0269', '57.5586', '1', 'f', 'f', '7', NULL, NULL, NULL);
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('a9164fa6-a19b-4789-866f-0f967dcde449', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'north-tour', 'activity'::activity_type, 'Private North Tour Mauritius', 'Private full-day tour of North Mauritius with a driver-guide: Port Louis and its central market, the Pamplemousses Botanical Garden, Grand Baie and the red-roof church of Cap Malheureux.', 'Discover the beauty, culture, and history of North Mauritius on this private full-day tour. Travel comfortably with an experienced local driver-guide and explore some of the island''s most famous attractions.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('2938b5c4-9734-4dfd-84c0-4bfc46e9facb', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'port-louis-city-tour', 'activity'::activity_type, 'Port Louis City Tour', 'A private, personalised tour through the capital Port Louis, taking in viewpoints, Hindu temples, the Caudan Waterfront, Chinatown and bazaar, the Citadel Fort and the Odysseo Oceanarium with an English/French-speaking driver.', 'Embark on a captivating journey through the heart of Mauritius with the Port Louis City Tour, a comprehensive exploration of the capital''s rich tapestry of history, culture, and contemporary allure. The tour begins at the Marie Reine de la Paix Viewpoint, a serene haven with sweeping views of Port Louis framed against the Moka mountain range. Next, visitors immerse themselves in the spiritual and architectural grandeur of vibrant Hindu temples adorned with intricate carvings and vivid colors. The Caudan Waterfront presents the modern face of Mauritius—a bustling promenade featuring shopping, dining, and entertainment with stunning harbor views. The journey continues through Chinatown''s narrow streets and traditional shops, the historic bazaar with its colors and scents, and museums providing deeper cultural understanding. The Citadel Fort, perched atop a hill, offers panoramic views spanning the cityscape and harbor. The tour concludes at the Odysseo Oceanarium, a state-of-the-art facility showcasing diverse marine life and aquatic ecosystems. Throughout the experience, visitors gain profound understanding of the island''s past and present through a private, personalized journey with an English/French-speaking driver.', 'Taxi Sightseeing tours', 'North West', '360', NULL, 't', '{English,French}'::text[], '{"Pick up and drop off from any hotel or Airbnb in Mauritius","Private transportation to all sights","English/French-speaking driver to guide and provide information","First child seat (free of charge, upon request)"}'::text[], '{"Entry ticket fees to places (Blue Penny Museum, etc.)","Lunch (customers choose restaurants; driver offers recommendations)"}'::text[], '{}'::text[], NULL, 'published'::activity_status, NULL, NULL, NULL, '0', '2026-06-19 20:14:04.421184+00', '{"itinerary": [{"area": "Capital", "tags": [], "title": "Port-Louis Caudan Waterfront", "description": null}, {"area": "Capital", "tags": ["Market", "Bazzar"], "title": "Chinatown", "description": null}, {"area": "Capital", "tags": [], "title": "Citadel Fort", "description": null}, {"area": "Capital", "tags": [], "title": "Odysseo Oceanarium", "description": null}, {"area": "Capital", "tags": [], "title": "Tamil Temple", "description": null}]}'::jsonb, '10', 'vehicle', 'f', NULL, '-20.1601', '57.4977', '1', 'f', 'f', '8', NULL, NULL, NULL);
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('7561c830-bc5a-4aaa-b72f-26774a53fd0b', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-full-day-3-northern-island-speed-boat-with-lunch-bbq', 'activity'::activity_type, 'Private Full Day 3 Northern Island Speed Boat with Lunch(BBQ)', 'Enjoy an exclusive private speedboat day trip from Grand Baie to Flat Island, Gabriel Island, and Gunner''s Coin. Cruise at your own pace, discover crystal-clear lagoons, snorkel in vibrant marine waters, and relax on pristine beaches. Your experience includes a delicious BBQ lunch served on the island, along with a selection of refreshing beverages throughout the day. Perfect for couples, families, or small groups seeking a personalized island adventure.', 'Enjoy an exclusive private speedboat day trip to discover three of the northern islands of Mauritius. Departing from Grand Baie, you''ll cruise for approximately 45 minutes to Flat Island, where you can relax on the beach, swim in crystal-clear waters, or snorkel in the beautiful lagoons.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('dcac8588-b2f3-4802-959f-970d1aa88755', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-full-day-3-northern-islands-adventure', 'activity'::activity_type, 'Private Full Day 3 Northern Islands Adventure', 'Enjoy a private full-day catamaran cruise from Grand Baie to Île Plate, featuring lagoon snorkeling, a gourmet lunch served on board, relaxation at Île aux Gabriel, and breathtaking views of Coin de Mire.', 'Depart from Grand Baie on your private catamaran for a full-day cruise to Île Plate. Snorkel in the crystal-clear lagoon, home to vibrant coral reefs and a variety of tropical fish. Enjoy a delicious gourmet lunch served on board as you sail through the stunning turquoise waters. Relax on the pristine beach of Île aux Gabriel or unwind on the spacious catamaran at your own pace. End your unforgettable day with breathtaking views of the dramatic cliffs of Coin de Mire before returning to Grand Baie.', 'Private Cruises', 'North', '420', 'Grand Baie', 'f', '{English}'::text[], '{"Lunch with salads","Garlic butter bread","Grilled chicken/fish/sausage","Water, Coke, beer, wine, local rum","Flaming banana","Fruit salads",Snorkeling}'::text[], '{"Do not drink if you are going to drive","Arrive 15 minutes before departure","Own transport users must find directions on Google Maps"}'::text[], '{"Île Plate (Northern Region)","Ile Aux Gabriel (Northern Region)","Coin de Mire (Northern Region)","Snorkeling (Northern Region)"}'::text[], 'Free cancellation up to 24 hours before your activity for a full refund.', 'published'::activity_status, NULL, NULL, NULL, '0', '2026-07-13 17:01:55.137323+00', '{"itinerary": [{"area": null, "tags": [], "title": "Grand Baie, Sunset Boulevard", "description": "Departure"}, {"area": null, "tags": [], "title": "Gunner''s Quoin", "description": "Snorkeling"}, {"area": null, "tags": [], "title": "Gabriel Island", "description": "Visit"}, {"area": null, "tags": [], "title": "Flat Island", "description": "Sightseeing"}], "whatToBring": ["Comfortable shoes", "Sunglasses", "Hat", "Swimwear", "Change of clothes", "Towel", "Camera", "Sunscreen", "Snorkeling gear"], "importantInfo": ["Infants aged 1 to 4 go free of charge.", "All food is halal. Vegetarian meals must be requested in advance.", "Pickup and drop-off is available if the applicable option is selected.", "Public parking is available 60m from the meeting point. Please arrive early to secure a space. Contact our team on WhatsApp for the location.", "The itinerary may be adjusted due to weather, sea conditions, tides, or operational requirements for guest safety.", "The captain’s decisions regarding navigation, timing, and itinerary adjustments are final and made in the interest of guest safety.", "Guests using wheelchairs need to stand briefly to get on and off the shuttle boat, with our crew assisting, to access the catamaran.", "For their own comfort and security, guests are kindly requested to keep personal belongings with them at all times. The company cannot be held responsible for any loss, theft, damage, or misplacement of personal items during the tour."]}'::jsonb, '10', 'per_person', 'f', 'North', '-20.006', '57.5824', '7', 'f', 'f', '2', NULL, NULL, NULL);
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('83ec6f71-6e52-4406-ad53-74ab45d1bd21', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-full-day-5-islands-tour-ile-aux-cerfs-with-lunch', 'activity'::activity_type, 'Private Full Day 5 Islands tour Ile Aux Cerfs with Lunch', 'Enjoy a private full-day speedboat excursion from Trou d''Eau Douce, visiting the GRSE waterfall, snorkeling among vibrant coral gardens, exploring the five islands, savoring a BBQ lunch, and relaxing on the beautiful northern beaches of Île aux Cerfs.', 'Embark on a private speedboat excursion from Trou d''Eau Douce for a full day of adventure and relaxation.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('ca8a0ff4-e24d-4712-ac91-457ee60d6c04', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-full-day-catamaran-ile-aux-cerfs', 'activity'::activity_type, 'Private Full Day Catamaran Ile Aux Cerfs', 'Set sail on a private full-day catamaran cruise from Trou d''Eau Douce and experience an unforgettable day with a visit to the Grand River South East Waterfall, snorkeling in turquoise lagoons, a gourmet BBQ lunch on board, and a relaxing stop at the idyllic Île aux Cerfs.', 'Enjoy an exclusive full-day private catamaran cruise departing from Trou d''Eau Douce on Mauritius'' east coast. Cruise to the spectacular Grand River South East Waterfall, snorkel in crystal-clear waters, and savor a delicious BBQ lunch with beverages served on board. Continue to the idyllic Île aux Cerfs, where you can unwind on pristine white-sand beaches, swim in the turquoise lagoon, and soak up the beauty of this tropical paradise at your own pace.', 'Private Cruises', 'Trou D''eau Douce', '420', 'Route Royale Maho, Trou d''Eau Douce', 't', '{English}'::text[], '{"Salads and garlic butter bread","BBQ items: chicken, fish, sausage","Beverages: water, Coke, beer, wine, local rum","Dessert: flaming banana",Snorkeling}'::text[], '{"Water Activities (Parasailing etc)"}'::text[], '{"Ile aux Cerfs (Eastern Region)","GRSE Waterfall (Eastern Region)","Snorkeling (Eau Bleu)","Lunch BBQ & Drinks on board"}'::text[], 'Free cancellation up to 24 hours before your activity for a full refund.', 'published'::activity_status, NULL, NULL, NULL, '0', '2026-07-12 16:34:56.545211+00', '{"itinerary": [{"area": null, "tags": [], "title": "Route Royale Maho, Trou d''Eau Douce", "description": "Departure"}, {"area": null, "tags": [], "title": "Grand River South East Waterfall", "description": "Sightseeing"}, {"area": null, "tags": [], "title": "Ile aux cerfs", "description": "Snorkeling + BBQ Lunch & Drinks on Board"}, {"area": null, "tags": [], "title": "Ile aux cerfs", "description": "Swimming & relaxation"}], "startWindow": "09:00", "whatToBring": ["Comfortable shoes", "Sunglasses", "Hat", "Swimwear", "Change of clothes", "Towel", "Camera", "Sunscreen", "Snorkeling gear"], "importantInfo": ["Arrive at boarding point at least 15 minutes before the cruise start time", "Guests using own transport must not drink if driving", "All food is halal. Vegetarian meals must be requested in advance.", "Pickup and drop-off is available if the applicable option is selected.", "Public parking is available 60m from the meeting point. Please arrive early to secure a space. Contact our team on WhatsApp for additional information.", "The itinerary may be adjusted due to weather, sea conditions, tides, or operational requirements for guest safety.", "The captain''s decisions regarding navigation, timing, and itinerary adjustments are final and made in the interest of guest safety.", "Guests using wheelchairs need to stand briefly to get on and off the shuttle boat, with our crew assisting, to access the catamaran.", "For their own comfort and security, guests are kindly requested to keep personal belongings with them at all times. The company cannot be held responsible for any loss, theft, damage, or misplacement of personal items during the tour."]}'::jsonb, '10', 'per_group', 'f', 'East', '-20.2428', '57.7868', '3', 'f', 'f', '1', 'Lobster for lunch', '2500', NULL);
