insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('0abf85b6-6b03-45f4-af7a-8d0b341af6b0', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-full-day-dolphin-swimming-ile-aux-benitiers-with-lunch', 'activity'::activity_type, 'Private Full day dolphin swimming Ile aux Bénitiers with lunch', 'Experience an exclusive private speedboat excursion along the stunning west coast of Mauritius. Set off on a full-day adventure to swim with dolphins in their natural habitat, snorkel in crystal-clear waters teeming with marine life, visit the iconic Crystal Rock, and unwind on the beautiful shores of Île aux Bénitiers. Your private experience also includes a delicious barbecue lunch served on the island, making it the perfect day of relaxation, exploration, and unforgettable memories.', 'Enjoy an exclusive full-day private speedboat excursion along the spectacular west coast of Mauritius. This personalized experience offers the opportunity to encounter dolphins in their natural habitat, explore vibrant underwater ecosystems while snorkeling, visit the iconic Crystal Rock, and relax on the idyllic shores of Île aux Bénitiers.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('59b0f6e2-a847-4418-9e3a-695a333465e4', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-full-day-speed-boat-ile-aux-cerf-with-lunch', 'activity'::activity_type, 'Private Full Day Speed Boat Ile Aux Cerf with Lunch', 'Enjoy a full-day excursion on your own private speedboat to Île aux Cerfs — cruise turquoise lagoons, witness the Grande Rivière Sud Est waterfall, savour a BBQ lunch on Îlot Mangénie, and add on water activities at your leisure.', 'Enjoy an unforgettable experience with your own private boat trip to Île aux Cerfs.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('8d143960-f55b-4658-9a9d-d798726207f0', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-full-day-western-cruise-catamaran', 'activity'::activity_type, 'Private Full Day Western Cruise Catamaran', 'Enjoy a private catamaran cruise to Tamarin Bay, where you''ll search for dolphins in their natural habitat, snorkel near a vibrant coral reef, and savor a delicious lunch at anchor beside the iconic Crystal Rock.', 'Set sail on your private catamaran towards Tamarin Bay in search of dolphins in their natural habitat, offering a magical and unforgettable wildlife experience. Later, stop at a beautiful coral reef to snorkel in crystal-clear waters and discover the vibrant marine life beneath the surface. Enjoy a delicious lunch served on board while anchored beside the iconic Crystal Rock, surrounded by the breathtaking scenery of Mauritius.', 'Private Cruises', 'West', '420', 'Black River', 't', '{English}'::text[], '{"Lunch on board: salads","Garlic butter bread","Chicken, fish, sausage","Water, Coke, beer, wine, local rum","Flaming banana","Fruit salads",Snorkeling}'::text[], '{"Please, do not drink if you are going to drive!","Arrive at boarding point at least 15 minutes before start","Own transport requires directions from Google Maps"}'::text[], '{"Departure from Black River (West region)","Dolphin watching at Tamarin Bay","Crystal Rock snorkeling (West region)","Benitier Island (West region)","Lunch on board (West region)"}'::text[], 'Free cancellation up to 24 hours before your activity for a full refund.', 'published'::activity_status, NULL, NULL, NULL, '0', '2026-07-13 17:16:14.291994+00', E'{"itinerary": [{"area": null, "tags": [], "title": "Black River", "description": "Departure"}, {"area": null, "tags": [], "title": "Tamarin", "description": "Secret Spot\\nDolphin Watching"}, {"area": null, "tags": [], "title": "Crystal Rock, Tamarin", "description": "Snorkeling"}, {"area": null, "tags": [], "title": "Benitier Island", "description": "Lunch on Board"}], "whatToBring": ["Comfortable shoes", "Sunglasses", "Hat", "Swimwear", "Change of clothes", "Towel", "Camera", "Sunscreen", "Snorkeling gear"], "importantInfo": ["Infants aged 1 to 4 go free of charge.", "All food is halal. Vegetarian meals must be requested in advance.", "Pickup and drop-off is available if the applicable option is selected.", "Public parking is available 60m from the meeting point. Please arrive early to secure a space. Contact our team on WhatsApp for the location.", "The itinerary may be adjusted due to weather, sea conditions, tides, or operational requirements for guest safety.", "The captain’s decisions regarding navigation, timing, and itinerary adjustments are final and made in the interest of guest safety.", "Guests using wheelchairs need to stand briefly to get on and off the shuttle boat, with our crew assisting, to access the catamaran.", "For their own comfort and security, guests are kindly requested to keep personal belongings with them at all times. The company cannot be held responsible for any loss, theft, damage, or misplacement of personal items during the tour."]}'::jsonb, '10', 'per_person', 'f', 'West', '-20.3615', '57.367', '5', 'f', 'f', '4', NULL, NULL, NULL);
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('bedf9528-77e9-4f62-9be3-f0726f38ea40', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-luxury-speedboat-5-island', 'activity'::activity_type, 'Private Luxury Speedboat 5 Island', 'Enjoy a private full-day on luxury speedboat excursion from Trou d''Eau Douce, visiting the GRSE waterfall, snorkeling among vibrant coral gardens, exploring the five islands, savoring a BBQ lunch, and relaxing on the beautiful northern beaches of Île aux Cerfs.', 'Embark on a private luxury speedboat excursion from Trou d''Eau Douce for a full day of adventure and relaxation.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('f286759a-7721-4414-b8fd-dc164eb3120c', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-shopping-tour', 'activity'::activity_type, 'Private Shopping Tour', 'All day or half a day: Shopping in Mauritius can be a wonderful experience. Traditional arts and crafts, as well as the finest luxury products, can be found in various shopping centers and boutiques.', 'All day or half a day: Shopping in Mauritius can be a wonderful experience. Traditional arts and crafts, as well as the finest luxury products, can be found in various shopping centers and boutiques.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('fb842149-9737-469b-a116-4b2b25230456', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-south-east-tour', 'activity'::activity_type, 'Private South East Tour', 'Explore the South-East Tour and uncover Mauritius’ rich history, cultural heritage, and scenic hidden gems.', 'Discover the wonders of Mauritius on our South-East Tour, a captivating journey through the island’s history, culture, and natural beauty. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('8b2bff90-c935-424a-871a-a7d0b3047ca1', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'private-swimming-with-dolphins-only', 'activity'::activity_type, 'Private Swimming with Dolphins Only', 'Enjoy an exclusive early-morning speedboat trip to Tamarin Bay to swim with wild dolphins in their natural habitat, followed by snorkeling over vibrant coral reefs. This private excursion offers a more personalized and flexible experience at your own pace.', 'Make your trip to Mauritius truly unforgettable with an exclusive private dolphin swimming experience. Set off early at 7:30 AM aboard your private speedboat and cruise to Tamarin Bay, where you''ll encounter wild dolphins in their natural habitat. Enjoy the freedom of a personalized excursion at your own pace as you slip into the crystal-clear waters to observe these magnificent creatures up close. Listen to their calls, admire their graceful movements, and experience an extraordinary connection with nature in a peaceful, uncrowded setting.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('46f8ee0b-3c53-4c77-9461-a8d6a237267e', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'scubadiving', 'activity'::activity_type, 'Scuba Diving', 'Explore the breathtaking underwater scenery of Mauritius, with colourful corals and a rich variety of fish in crystal-clear waters.', 'Diving in Mauritius provides an unforgettable and extraordinary experience as you explore breathtaking underwater scenery, where colorful corals form enchanting landscapes teeming with an astonishing variety of shimmering fish. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('e0a2004b-4f7a-46a2-95f7-c7866c4980c9', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'seaplane', 'activity'::activity_type, 'Fly Over the Underwater Waterfall: Mauritius Seaplane Tour', 'Take off barefoot from the turquoise lagoon at La Prairie beach and fly beside the famous underwater waterfall illusion, next to a UNESCO World Heritage site.', 'We have the privilege of flying over the UNDERWATER CASCADE daily. Our seaplanes take off from the beach of La Prairie, right next to this natural wonder. Just a few steps away, barefoot in the turquoise lagoon, you board the seaplane. Get ready to take off from the crystal-clear waters, beside a UNESCO World Heritage site. Comfortably seated next to the pilot, you will discover this famous illusion: a waterfall at the bottom of the Indian Ocean. It''s magical and majestic. The most photogenic view has captivated the entire world since its photos made their rounds on the internet. This natural treasure is truly something to see in person.', 'Air Activity', 'East', NULL, NULL, 't', '{English,French}'::text[], '{}'::text[], '{}'::text[], '{"Fly over the famous underwater waterfall illusion at the bottom of the Indian Ocean","Take off barefoot from the turquoise lagoon at La Prairie beach","Seated next to the pilot","Views beside a UNESCO World Heritage site","Three tour options: 15min (the short ambre), 30min (the Turquoise experience), 60min (the mythical east)"}'::text[], NULL, 'published'::activity_status, NULL, NULL, NULL, '0', '2026-06-19 20:14:04.421184+00', '{"importantInfo": ["Please arrive at the boarding point at least 15 minutes before your scheduled departure time.", "Directions to the boarding point are available on Google Maps.", "Please do not drink if you are going to drive!", "Pickup and drop-off available throughout the island.", "50% cancellation fee for cancellations within 24 hours of the excursion.", "100% cancellation fee for cancellations on the day of the excursion.", "If the cancellation is made by Belle Mare Tours Ltd, a full refund will be issued via bank transfer to the customer''s account.", "Payment Methods: Payment can be made in cash to the driver in MUR, EUR, or USD, or online prior to your tour."]}'::jsonb, NULL, 'per_person', 'f', 'North', '-20.2385', '57.7905', '1', 'f', 'f', '1', NULL, NULL, NULL);
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('4cadf649-b9db-4911-96f4-cc10d67aa981', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'skydive', 'activity'::activity_type, 'Tandem Skydiving in Mauritius', 'Tandem skydive from 10,000 feet over Mon Loisir''s sugarcane fields, freefalling at 200 km/h before gliding down over the lagoons and reefs of the Indian Ocean.', 'Enjoy the spectacular views of Mauritius with a tandem skydive. Soar through the skies while securely harnessed to your experienced instructor. Experience a 360 degree view of the stunning coastline, interior, and mountains before your jump. This adrenaline-pumping activity is suitable for both beginners and experienced thrill-seekers alike. At 10,000 feet, you''ll freefall at 200 km/h for a minute, then glide for 5 minutes before landing safely. Feel the rush of excitement as you plummet towards the earth surrounded by breathtaking panoramas. Take off from Mon Loisir''s beautiful sugarcane fields overlooking the lagoons and reefs of the Indian Ocean. After the exhilarating experience, relax and reflect on your adventure while enjoying refreshments at the drop zone. The whole skydiving excursion lasts about 1 hour, including ground training, 25 minutes of flight, freefall, and parachute descent. Celebrate your bravery and sense of achievement with friends and family who can witness your jump and cheer you on. Receive a tandem skydiving certificate and opt for a DVD of your jump as a keepsake at an additional cost. Make sure to book in advance to secure your spot for this unforgettable adventure in Mauritius.', 'Air Activity', 'Royal Road, Belle Mare, Mauritius', '60', NULL, 't', '{English,French}'::text[], '{"Tandem skydive from 10,000 feet","Ground training","25 minutes of flight","Freefall and parachute descent","Tandem skydiving certificate","Refreshments at the drop zone","Pickup and drop-off at all island locations"}'::text[], '{"DVD of your jump (additional cost: Rs 5000)","Photos (additional cost: Rs 6500)","Do not drink if you are driving your own transport"}'::text[], '{"360 degree panoramic views of the coastline, interior, and mountains","Take off from Mon Loisir''s sugarcane fields overlooking the lagoons and reefs of the Indian Ocean","Freefall at 200 km/h for one minute","Glide descent for 5 minutes","Refreshments at the drop zone"}'::text[], NULL, 'published'::activity_status, NULL, NULL, NULL, '0', '2026-06-19 20:14:04.421184+00', '{"inquiryOnly": true, "startWindow": "08:30", "importantInfo": ["Please arrive at the boarding point at least 15 minutes before your scheduled departure time.", "Directions to the boarding point are available on Google Maps.", "Please do not drink if you are going to drive!", "Pickup and drop-off available throughout the island.", "50% cancellation fee for cancellations within 24 hours of the excursion.", "100% cancellation fee for cancellations on the day of the excursion.", "If the cancellation is made by Belle Mare Tours Ltd, a full refund will be issued via bank transfer to the customer''s account.", "Payment Methods: Payment can be made in cash to the driver in MUR, EUR, or USD, or online prior to your tour."]}'::jsonb, NULL, 'per_person', 'f', 'North', '-20.1875', '57.771', '1', 'f', 'f', '0', NULL, NULL, NULL);
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('1c5af259-7dca-4a18-9e53-3cf51e8c8b36', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'south-tour-mauritius', 'activity'::activity_type, 'Private South Tour Mauritius', 'Places to discover during this visit to the south: Trou Aux Cerfs (Volcan), Floréal (Shopping), Grand Bassin – Sacred lake of the Hindu temple, Black River Gorges – Viewpoint, Chamarel 7-color earth + waterfall, Viewpoint of Bénitier Island', 'In the highlands, discover the impressive Trou aux Cerfs, the crater of a volcano that has been extinct for 700,000 years. From there, you will have a stunning view of the mountainous ring of Mauritius.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('0067e1c1-e08c-4c1b-a2ea-d66e9e285d05', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'speed-boat-ile-aux-cerfs', 'activity'::activity_type, 'Full Day Speed Boat Ile Aux Cerf with Lunch', 'A full-day speedboat trip to Île aux Cerfs with turquoise lagoons, the Grande Rivière Sud Est waterfall, a BBQ lunch on Îlot Mangénie and optional water activities.', 'Enjoy an unforgettable experience with a boat trip to Île aux Cerfs. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('d29e7a9e-9197-4c05-afcc-ad9f370668c5', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'swimming-with-dolphins', 'activity'::activity_type, 'Swimming with Dolphins Only', 'Early-morning speedboat trip to Tamarin Bay to swim with wild dolphins in their natural habitat, followed by snorkeling over coral reefs.', 'Make your trip to Mauritius truly unforgettable with the magical experience of swimming alongside dolphins. Set off early at 7:30 AM on a speedboat and head to Tamarin Bay, where you''ll meet these incredible creatures in their natural habitat. Feel the thrill as you dive into crystal-clear waters and watch dolphins play just a few feet away. Listen to their calls, observe their graceful movements, and enjoy a unique moment of connection with nature. This extraordinary adventure will fill you with joy, wonder, and an unmatched sense of freedom.
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('f328f009-1ab5-442b-ab0a-90d052ffe3eb', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'swimming-with-dolphins-benitier-island-speedboat-all-inclusive', 'activity'::activity_type, 'Full day dolphin swimming Ile aux Bénitiers with lunch', 'Full-day speedboat excursion in western Mauritius: swim with dolphins, snorkel, visit Crystal Rock, and enjoy a barbecue lunch on Ile aux Benitiers.', 'This full-day speedboat excursion offers an immersive ocean experience in Mauritius''s western region. 
insert into activities ("id", "operator_id", "slug", "type", "title", "summary", "description", "category", "location", "duration_minutes", "meeting_point", "pickup_available", "languages", "inclusions", "exclusions", "highlights", "cancellation_policy", "status", "seo_title", "seo_description", "rating_avg", "rating_count", "created_at", "extra", "daily_capacity", "pricing_mode", "is_custom_planner", "region", "lat", "lng", "min_advance_days", "is_airport_transfer", "is_hotel_transfer", "sort", "supplement_name", "supplement_minor", "guests_per_trip") values ('6527f2f3-5e9a-4823-956f-3079253e07d7', 'bb34e08d-d570-491e-8ff6-ca9d401b2a82', 'tea-tasting-tour', 'activity'::activity_type, 'Private South - Tea Tasting', 'Explore South Mauritius with a personal driver-guide, including Bois Chéri tea plantation/factory, Saint Aubin colonial house and rum distillery.', 'Bois Chéri is one of the most important tea factories on the island. You will discover the different stages of production while enjoying a nice cup of tea. You will have a personal driver-guide to take you on a tour and provide you with information, offering a personalized service. 
