insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('b915b04f-ac4c-461f-8adc-d05988d50ef0', '0067e1c1-e08c-4c1b-a2ea-d66e9e285d05', 'fr'::content_locale, 'Speedboat d’une journée complète – Île aux Cerfs avec déjeuner', 'Une excursion d’une journée complète en speedboat vers l’Île aux Cerfs, avec ses lagons turquoise, la cascade de la Grande Rivière Sud-Est, un déjeuner BBQ sur l’Îlot Mangénie et des activités nautiques en option.', 'Vivez une expérience inoubliable avec cette excursion en bateau vers l’Île aux Cerfs.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('a027b5ca-e7ab-4f52-b1b8-c363974f2373', '0abf85b6-6b03-45f4-af7a-8d0b341af6b0', 'fr'::content_locale, 'Journée privée nage avec les dauphins à l’Île aux Bénitiers avec déjeuner', 'Vivez une excursion privée exclusive en speedboat le long de la magnifique côte Ouest de Maurice. Partez pour une journée d’aventure à la nage avec les dauphins dans leur habitat naturel, faites du snorkeling dans des eaux cristallines foisonnant de vie marine, visitez l’emblématique Crystal Rock et détendez-vous sur les magnifiques rives de l’Île aux Bénitiers. Votre expérience privée comprend également un délicieux déjeuner barbecue servi sur l’île, pour une journée parfaite de détente, d’exploration et de souvenirs inoubliables.', 'Profitez d’une excursion privée exclusive en speedboat, d’une journée complète, le long de la côte Ouest spectaculaire de Maurice. Cette expérience personnalisée vous offre l’occasion de rencontrer des dauphins dans leur habitat naturel, d’explorer de superbes écosystèmes sous-marins en faisant du snorkeling, de visiter l’emblématique Crystal Rock et de vous détendre sur les rives idylliques de l’Île aux Bénitiers.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('aea9b0fc-3966-40d7-8cb2-e08c0c21cbb2', '177e8323-a359-4233-852a-c3a7ae083759', 'fr'::content_locale, 'Croisière catamaran au coucher du soleil', 'Naviguez paisiblement au fil d’un magnifique coucher de soleil au-dessus de Grand Baie à bord d’un superbe catamaran, tout en savourant un cocktail rafraîchissant.', 'Naviguez paisiblement au fil d’un magnifique coucher de soleil au-dessus de Grand Baie à bord d’un superbe catamaran, tout en savourant un cocktail rafraîchissant. Les couchers de soleil sur la côte nord-ouest de Maurice sont légendaires, et la meilleure façon de les admirer est depuis l’océan.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('23eb11c2-9780-4dcf-8e02-677de0d7b6b3', '1bfe0559-037f-40f7-8384-4ae938f6b23d', 'fr'::content_locale, 'Visite de l’Île d’Ambre en kayak', 'Pagayez en kayak à travers les mangroves paisibles de l’Île d’Ambre, explorez ses recoins secrets et ses ruines anciennes, puis détendez-vous sur l’Île Bernache.', 'Pagayez en kayak à travers les mangroves de l’Île d’Ambre et découvrez son environnement d’une manière unique et immersive. Imprégnez-vous de la beauté naturelle qui entoure ces eaux paisibles et observez la faune et la flore locales dans leur habitat naturel.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('32ceecdc-1562-4d7e-8c8b-afd75e044710', '1c5af259-7dca-4a18-9e53-3cf51e8c8b36', 'fr'::content_locale, 'Circuit privé dans le Sud de l’île Maurice', 'Lieux à découvrir lors de cette visite du Sud de l’île Maurice : le Trou aux Cerfs, un ancien volcan offrant des vues panoramiques spectaculaires ; Floréal, réputé pour ses boutiques et son artisanat local ; Grand Bassin (Ganga Talao), le lac sacré et haut lieu de pèlerinage hindou ; les gorges de la Rivière Noire et leurs magnifiques points de vue ; la Terre des Sept Couleurs de Chamarel et sa célèbre cascade ; ainsi qu’un superbe point de vue sur l’Île aux Bénitiers.', 'Perché sur les hauteurs de Curepipe, découvrez l’impressionnant Trou aux Cerfs, le cratère d’un volcan éteint depuis plus de 700 000 ans. Depuis son sommet, profitez d’une vue panoramique exceptionnelle sur la chaîne de montagnes du centre de l’île Maurice.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('d85c932d-c4dc-46fd-9a65-e065cd3ae9b2', '2402ab1e-1695-4485-a120-561d08797854', 'fr'::content_locale, 'Circuit des plages du Nord', 'Une excursion privée exclusive d’une journée à la découverte de cinq plages du Nord de Maurice, avec chaises longues, parasol, natte, collations et boissons offerts, et un chauffeur parlant anglais et français.', 'Une excursion privée exclusive à la découverte de cinq plages du Nord de Maurice en une seule journée. Un chauffeur dédié vous emmène à Trou aux Biches, Mont Choisy, La Cuvette, Grand Baie et Pereybère. L’expérience comprend chaises longues, parasols, nattes, collations et boissons rafraîchissantes offerts. Chaque plage a ses particularités : Mont Choisy séduit par ses eaux cristallines et sa vie marine ; Pereybère offre une ambiance animée avec ses cafés locaux ; Grand Baie propose sports nautiques et shopping ; Trou aux Biches offre un cadre paisible, idéal en famille ; La Cuvette est une échappée isolée et tranquille. Le chauffeur vous aide à installer votre coin plage et vous accompagne en anglais et en français tout au long de la journée.', '{"Plage de Trou aux Biches","Plage de Mont Choisy","Plage de La Cuvette","Plage de Grand Baie","Plage de Pereybère"}'::text[], '{"Prise en charge et dépose depuis n’importe quel hôtel ou Airbnb à Maurice","Véhicule privé et transport entre les plages","Chauffeur parlant anglais et français","Arrêt au supermarché en chemin","Un parasol, deux chaises longues, une natte de plage (minimum)","Collations et boissons fraîches","Premier siège enfant (sur demande)"}'::text[], '{"Déjeuner non inclus (le chauffeur peut recommander des restaurants)","Billets d’entrée aux sites visités","Chaises longues/parasols supplémentaires au-delà des quantités indiquées"}'::text[], NULL, NULL, NULL, 'machine', '{"itinerary": [{"area": "Région Nord", "tags": [], "title": "Grand Bay Beach", "description": null}, {"area": "Région Nord", "tags": [], "title": "Pereybere Beach", "description": null}, {"area": "Région Nord", "tags": [], "title": "Mont Choisy Beach", "description": null}, {"area": "Région Nord", "tags": [], "title": "Trou Aux Biches", "description": null}, {"area": "Région Nord", "tags": [], "title": "Cap Malheureux", "description": null}]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('d5286bbb-b585-4e11-a0da-2228c2ad0ecf', '268a885f-c018-452e-add8-9cf72ecc2f60', 'fr'::content_locale, 'Pêche au gros', 'Pêchez le marlin bleu, la dorade coryphène et d’autres gros poissons sous la conduite de skippers expérimentés, à bord de bateaux modernes bien équipés.', 'Que vous soyez débutant ou expert, vous prendrez plaisir à pêcher le marlin bleu, la dorade coryphène ou d’autres gros poissons sous la conduite de skippers expérimentés. Les bateaux modernes conçus pour la pêche au gros sont bien équipés.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('a6e92fbd-f70e-4a40-8e08-2f0d526b0917', '2938b5c4-9734-4dfd-84c0-4bfc46e9facb', 'fr'::content_locale, 'Visite de la ville de Port-Louis', 'Une visite privée et personnalisée de la capitale Port-Louis, avec points de vue, temples hindous, le Caudan Waterfront, Chinatown et son bazar, la Citadelle et l’Odysseo Oceanarium, accompagnée d’un chauffeur parlant anglais et français.', 'Embarquez pour un voyage captivant au cœur de Maurice avec cette visite de la ville de Port-Louis, une exploration complète de la riche mosaïque d’histoire, de culture et de charme contemporain de la capitale. La visite débute au point de vue Marie Reine de la Paix, un havre serein offrant une vue dégagée sur Port-Louis, avec la chaîne de montagnes de Moka en toile de fond. Les visiteurs s’immergent ensuite dans la grandeur spirituelle et architecturale de temples hindous vibrants, ornés de sculptures raffinées et de couleurs éclatantes. Le Caudan Waterfront incarne le visage moderne de Maurice — une promenade animée mêlant shopping, restauration et divertissement, avec de superbes vues sur le port. La visite se poursuit dans les ruelles et les échoppes traditionnelles de Chinatown, le bazar historique avec ses couleurs et ses odeurs, ainsi que des musées offrant une compréhension culturelle plus approfondie. La Citadelle, perchée sur une colline, offre des vues panoramiques sur la ville et le port. La visite se termine à l’Odysseo Oceanarium, un établissement moderne présentant une vie marine et des écosystèmes aquatiques variés. Tout au long de cette expérience privée et personnalisée, accompagnée d’un chauffeur parlant anglais et français, les visiteurs acquièrent une compréhension profonde du passé et du présent de l’île.', '{}'::text[], '{"Prise en charge et dépose depuis n’importe quel hôtel ou Airbnb à Maurice","Transport privé vers tous les sites","Chauffeur parlant anglais et français pour vous guider et vous informer","Premier siège enfant (gratuit, sur demande)"}'::text[], '{"Frais d’entrée sur les sites (Blue Penny Museum, etc.)","Déjeuner non inclus (les clients choisissent leur restaurant ; le chauffeur propose des recommandations)"}'::text[], NULL, NULL, NULL, 'machine', '{"itinerary": [{"area": "Capitale", "tags": [], "title": "Port-Louis Caudan Waterfront", "description": null}, {"area": "Capitale", "tags": ["Marché", "Bazar"], "title": "Chinatown", "description": null}, {"area": "Capitale", "tags": [], "title": "Citadel Fort", "description": null}, {"area": "Capitale", "tags": [], "title": "Odysseo Oceanarium", "description": null}, {"area": "Capitale", "tags": [], "title": "Tamil Temple", "description": null}]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('503283b3-083a-4d9f-8c8c-255e2736a521', '2d78f6bf-902a-4296-ade4-5fa52a67cc65', 'fr'::content_locale, 'Casela World of Adventures', 'Excursion d’une journée à Casela World of Adventures, un parc naturel et de loisirs de 14 hectares avec safaris, tyroliennes, promenade avec les lions et activités familiales.', 'Bienvenue dans l’univers d’aventure de Casela. Rejoignez-nous pour une journée inoubliable remplie d’activités pour toute la famille !
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('7350483e-895e-4a07-beb4-d78613cc176d', '3da3c977-1c1a-4ca4-8aa6-4e5146460df7', 'fr'::content_locale, 'Blue Safari : sous-marin et Subscooter', 'Descendez dans les profondeurs de l’océan Indien en sous-marin ou en Subscooter pour explorer les récifs, les coraux, la vie marine et l’épave du « Le Star Hope ».', 'Découvrez peu à peu le monde sous-marin en observant la beauté de l’océan Indien et de sa vie marine. Vous recevrez un briefing avant l’embarquement à bord du sous-marin depuis une plateforme flottante. En descendant dans les profondeurs, vous explorerez les récifs, les coraux, la faune marine locale, l’épave du « Le Star Hope » et une ancienne ancre datant du XVIIe siècle, au fond de l’océan.', '{"Explorez les récifs et les coraux","Observez la faune marine locale","Découvrez l’épave du « Le Star Hope »","Découvrez une ancienne ancre du XVIIe siècle au fond de l’océan"}'::text[], '{"Briefing avant l’embarquement","Prise en charge et dépose partout sur l’île"}'::text[], '{"Ne buvez pas d’alcool si vous devez conduire","Arrivez au point d’embarquement au moins 15 minutes avant l’heure de départ"}'::text[], 'Trou aux Biches, route côtière', NULL, NULL, 'machine', NULL::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('b3417e77-1501-4f1a-bb9e-37dbc07f3c80', '419bcd80-9ba2-4cc8-adbe-db96d89831d2', 'fr'::content_locale, 'Tour en hélicoptère de Maurice', 'Découvrez Maurice vue du ciel lors d’un vol privé en hélicoptère au départ de la base de Triolet, dans le Nord, avec trois formules allant d’un court survol panoramique à un tour complet de l’île.', 'The Must (départ de Triolet, Nord) : Un vol court et des souvenirs gravés à jamais dans votre mémoire. L’itinéraire au départ de la base de Triolet comprend un survol des paysages et des îlots du Nord. Profitez de l’effervescence de Grand Baie vue du ciel et des bateaux alignés près de la plage de sable doré. Survolez ensuite le Coin de Mire, qui domine la côte Nord, et l’Île Plate, refuge de diverses espèces de reptiles. Le vol se termine par un magnifique passage au-dessus de l’Île d’Ambre, où le célèbre Saint-Géran a fait naufrage et qui servit de cadre à Paul et Virginie de Bernardin de Saint-Pierre.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('c321a434-b74a-4d96-80cb-16fdffe7ca6e', '46812499-46a5-482c-ac5c-b035b02929b3', 'fr'::content_locale, 'Randonnée dans les gorges de la Rivière Noire', 'Randonnée au cœur du parc national des gorges de la Rivière Noire à la découverte de cascades secrètes, d’une faune endémique et de vues panoramiques depuis la crête.', 'Explorez avec nous le cœur des gorges de la Rivière Noire et laissez-vous surprendre par des trésors cachés qui se révèlent peu à peu à vous.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('11433cfd-551c-4501-9a2a-8e641ce66f5d', '46f8ee0b-3c53-4c77-9461-a8d6a237267e', 'fr'::content_locale, 'Plongée sous-marine', 'Explorez les paysages sous-marins à couper le souffle de Maurice, avec des coraux colorés et une riche variété de poissons dans des eaux cristallines.', 'Plonger à Maurice offre une expérience inoubliable et extraordinaire : vous explorez des paysages sous-marins à couper le souffle, où des coraux colorés forment des paysages enchanteurs grouillant d’une étonnante variété de poissons chatoyants.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('e34e2174-15cb-4156-be57-1bc000c53be7', '4c1ec0a9-00ce-49d6-8554-da65bf3a74c6', 'fr'::content_locale, 'Road trip sur mesure', 'Concevez votre propre journée à travers Maurice avec le planificateur IA — un prix fixe unique par véhicule.', NULL, '{}'::text[], '{}'::text[], '{}'::text[], NULL, NULL, NULL, 'machine', NULL::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('21923e7f-2090-47ac-bc35-738ef273102b', '4cadf649-b9db-4911-96f4-cc10d67aa981', 'fr'::content_locale, 'Saut en parachute en tandem à Maurice', 'Sautez en parachute en tandem depuis 10 000 pieds au-dessus des champs de canne à sucre de Mon Loisir, avec une chute libre à 200 km/h avant une descente en vol plané au-dessus des lagons et récifs de l’océan Indien.', 'Profitez des vues spectaculaires de Maurice lors d’un saut en parachute en tandem. Envolez-vous dans les airs, solidement harnaché à votre instructeur expérimenté. Admirez une vue à 360 degrés sur le littoral, l’intérieur des terres et les montagnes avant votre saut. Cette activité riche en adrénaline convient aussi bien aux débutants qu’aux amateurs de sensations fortes expérimentés. À 10 000 pieds, vous effectuerez une chute libre à 200 km/h pendant une minute, puis une descente en vol plané de 5 minutes avant d’atterrir en toute sécurité. Ressentez la montée d’adrénaline en plongeant vers la terre, entouré de panoramas à couper le souffle. Décollez depuis les magnifiques champs de canne à sucre de Mon Loisir, surplombant les lagons et récifs de l’océan Indien. Après cette expérience grisante, détendez-vous et repensez à votre aventure en savourant des rafraîchissements sur la zone d’atterrissage. L’excursion complète de saut en parachute dure environ 1 heure, incluant l’entraînement au sol, 25 minutes de vol, la chute libre et la descente en parachute. Célébrez votre courage et votre sentiment d’accomplissement avec vos amis et votre famille, qui pourront assister à votre saut et vous encourager. Recevez un certificat de saut en parachute en tandem, et optez, moyennant un supplément, pour un DVD souvenir de votre saut. Pensez à réserver à l’avance pour garantir votre place lors de cette aventure inoubliable à Maurice.', '{"Vue panoramique à 360 degrés sur le littoral, l’intérieur des terres et les montagnes","Décollage depuis les champs de canne à sucre de Mon Loisir, surplombant les lagons et récifs de l’océan Indien","Chute libre à 200 km/h pendant une minute","Descente en vol plané de 5 minutes","Rafraîchissements sur la zone d’atterrissage"}'::text[], '{"Saut en parachute en tandem depuis 10 000 pieds","Entraînement au sol","25 minutes de vol","Chute libre et descente en parachute","Certificat de saut en parachute en tandem","Rafraîchissements sur la zone d’atterrissage","Prise en charge et dépose partout sur l’île"}'::text[], '{"DVD de votre saut (supplément : Rs 5 000)","Photos (supplément : Rs 6 500)","Ne buvez pas d’alcool si vous conduisez votre propre véhicule"}'::text[], NULL, NULL, NULL, 'machine', '{"importantInfo": ["Merci d’arriver au point d’embarquement au moins 15 minutes avant l’heure de départ prévue.", "L’itinéraire vers le point d’embarquement est disponible sur Google Maps.", "Merci de ne pas boire d’alcool si vous devez conduire !", "Prise en charge et retour disponibles partout sur l’île.", "Frais d’annulation de 50 % pour toute annulation dans les 24 heures précédant l’excursion.", "Frais d’annulation de 100 % pour toute annulation le jour de l’excursion.", "Si l’annulation est faite par Belle Mare Tours Ltd, un remboursement intégral sera effectué par virement bancaire sur le compte du client.", "Modes de paiement : le paiement peut être effectué en espèces auprès du chauffeur en MUR, EUR ou USD, ou en ligne avant votre excursion."]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('f3140d73-e201-4e93-a16f-24c3b183ab3a', '4dc413ac-04ef-433b-b0c3-b93b224c6e05', 'fr'::content_locale, 'Randonnée au Morne Brabant', 'Gravissez le Morne Brabant, site classé au patrimoine mondial de l’UNESCO, jusqu’à son sommet en « V » pour des vues spectaculaires sur des lagons turquoise et des chaînes de montagnes verdoyantes.', 'Découvrez la beauté et la majesté du Morne Brabant en gravissant la montagne depuis sa base jusqu’au sommet en « V », tout en admirant un paysage spectaculaire.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('2a69848b-6e24-4b7d-bd50-f711abd0d6b0', '4ffb45b2-365d-4884-afbc-84aca75de00f', 'fr'::content_locale, 'Excursion privée en Cataspeed des 5 îles', 'Découvrez la magnifique côte Est de Maurice avec la visite de la cascade de la Grande Rivière Sud-Est (GRSE), de cinq îles superbes et une incroyable séance de snorkeling dans des lagons aux eaux cristallines. Profitez de paysages à couper le souffle, observez une vie marine éclatante de couleurs et détendez-vous lors d’une inoubliable croisière en CataSpeed.', 'Votre croisière d’une journée complète débute à l’embarcadère public de Trou d’Eau Douce, où vous rencontrerez l’équipage avant de partir à la découverte de la magnifique côte Est de Maurice.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('c88c54c5-5f4d-4a3a-b68d-cfc4a21c8359', '56e84f5b-ac60-486c-8937-3aee22812365', 'fr'::content_locale, 'Excursion à la rencontre des baleines et baignade avec les dauphins', 'Une excursion en bateau sur la côte Ouest pour admirer les baleines à bosse ou les cachalots et nager avec les dauphins, sous la supervision de skippers et d’équipages professionnels.', 'Une expérience unique qui vous laissera des souvenirs pour toute une vie ! Plongez dans l’aventure d’une vie, qui vous mettra en contact avec des paysages d’une beauté saisissante, préservés, et de merveilleux animaux marins.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('bb38c4cc-1c2c-4e2d-885c-6f90cde4a327', '59b0f6e2-a847-4418-9e3a-695a333465e4', 'fr'::content_locale, 'Speedboat privé d’une journée complète – Île aux Cerfs avec déjeuner', 'Profitez d’une excursion d’une journée complète à bord de votre propre speedboat privé vers l’Île aux Cerfs — naviguez à travers des lagons turquoise, découvrez la cascade de la Grande Rivière Sud-Est, savourez un déjeuner BBQ sur l’Îlot Mangénie et ajoutez des activités nautiques selon vos envies.', 'Vivez une expérience inoubliable à bord de votre propre bateau privé jusqu’à l’Île aux Cerfs.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('f5756fd5-41d9-4ab0-a3fc-5b77acf2f701', '59d694e1-e076-4cec-b761-b462687e26a0', 'fr'::content_locale, 'Croisière en catamaran – Île aux Cerfs', 'Une croisière en catamaran d’une journée complète au départ de Trou d’Eau Douce, avec visite de la cascade de la Grande Rivière Sud-Est (GRSE), snorkeling, déjeuner BBQ à bord et Île aux Cerfs.', 'Profitez d’une croisière en catamaran d’une journée complète au départ de Trou d’Eau Douce, sur la côte Est de Maurice.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('7fb102e3-6e6c-46ac-96d1-48c6040875b4', '6527f2f3-5e9a-4823-956f-3079253e07d7', 'fr'::content_locale, 'Sud privé – Dégustation de thé', 'Explorez le Sud de Maurice avec un chauffeur-guide personnel, avec au programme la plantation et la fabrique de thé de Bois Chéri, ainsi que la maison coloniale et la distillerie de rhum de Saint Aubin.', 'Bois Chéri est l’une des fabriques de thé les plus importantes de l’île. Vous découvrirez les différentes étapes de la production tout en savourant une bonne tasse de thé. Un chauffeur-guide personnel vous accompagnera tout au long de la visite et vous informera, pour un service sur mesure.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('f2b5791e-a886-4a8b-bae9-ecc56a2b7e04', '67536211-95c6-447a-9bd3-55a9eb09cda5', 'fr'::content_locale, 'Cataspeed privé d’une journée complète – Île aux Cerfs', 'Embarquez pour une aventure privée en Cataspeed, d’une journée complète, au départ de Trou d’Eau Douce, et vivez une journée grisante sur l’eau avec la visite de la cascade de la Grande Rivière Sud-Est, du snorkeling dans des lagons aux eaux cristallines, un déjeuner BBQ gastronomique à bord et une halte détente à la magnifique Île aux Cerfs.', 'Profitez d’une aventure privée exclusive en Cataspeed, d’une journée complète, au départ de Trou d’Eau Douce, sur la côte Est de Maurice. Filez à travers le lagon turquoise jusqu’à la spectaculaire cascade de la Grande Rivière Sud-Est, faites du snorkeling dans des eaux cristallines et savourez un délicieux déjeuner BBQ avec boissons servi à bord. Poursuivez vers l’idyllique Île aux Cerfs, où vous pourrez vous détendre sur des plages de sable blanc immaculées, nager dans le lagon turquoise et profiter à votre rythme de la beauté de ce paradis tropical.', '{"Île aux Cerfs (région Est)","Cascade GRSE (région Est)","Snorkeling (Eau Bleue)","Déjeuner BBQ et boissons à bord"}'::text[], '{"Salades et pain au beurre à l’ail","BBQ : poulet, poisson, saucisse","Boissons : eau, Coca, bière, vin, rhum local","Dessert : banane flambée",Snorkeling}'::text[], '{"Activités nautiques (parachute ascensionnel, etc.)"}'::text[], 'Route Royale Maho, Trou d’Eau Douce', NULL, NULL, 'machine', '{"itinerary": [{"tags": [], "title": "Route Royale Maho, Trou d''Eau Douce", "description": "Départ"}, {"tags": [], "title": "Ile aux cerfs", "description": "Snorkeling + déjeuner BBQ et boissons à bord"}, {"tags": [], "title": "Ile aux cerfs", "description": "Baignade et détente"}, {"tags": [], "title": "Grand River South East Waterfall", "description": "Visite touristique"}], "whatToBring": ["Chaussures confortables", "Serviette", "Équipement de snorkeling", "Crème solaire", "Maillot de bain"], "importantInfo": ["Arrivez au point d’embarquement au moins 15 minutes avant le début de la croisière", "Les passagers utilisant leur propre véhicule ne doivent pas boire d’alcool s’ils conduisent", "Tous les repas sont halal. Les repas végétariens doivent être demandés à l’avance.", "La prise en charge et le retour sont disponibles si l’option correspondante est sélectionnée.", "Un parking public est disponible à 60 m du point de rendez-vous. Merci d’arriver tôt pour être sûr d’avoir une place. Contactez notre équipe sur WhatsApp pour plus d’informations.", "L’itinéraire peut être modifié en raison de la météo, de l’état de la mer, des marées ou de contraintes opérationnelles pour la sécurité des passagers.", "Les décisions du capitaine concernant la navigation, les horaires et les modifications de l’itinéraire sont définitives et prises dans l’intérêt de la sécurité des passagers.", "Les passagers en fauteuil roulant doivent se tenir debout brièvement pour monter à bord de la navette et en descendre, avec l’aide de notre équipage, afin d’accéder au catamaran.", "Pour leur confort et leur sécurité, les passagers sont invités à garder leurs effets personnels avec eux à tout moment. La société ne pourra être tenue responsable de toute perte, vol, dommage ou égarement d’objets personnels pendant l’excursion."]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('e94292aa-0f13-473a-8931-e184782437fe', '67b2f533-d3c5-47cb-98cf-456c45f44130', 'fr'::content_locale, 'Balade à cheval sur la plage', 'Découvrez le parfait équilibre entre aventure et détente lors d’une balade à cheval guidée le long des magnifiques plages de Maurice. À Belle Mare Beach, nos balades vous permettent d’admirer le littoral à couper le souffle de l’île tout en vivant une expérience inoubliable au cœur de la nature.', 'Que vous soyez un cavalier expérimenté ou que vous essayiez l’équitation pour la première fois, Belle Mare Tours propose des balades à cheval guidées, conçues pour être sûres, relaxantes et mémorables.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('72a7eadf-a712-43fd-a1fc-21946aae1f93', '7561c830-bc5a-4aaa-b72f-26774a53fd0b', 'fr'::content_locale, 'Journée privée en speedboat aux 3 îles du Nord avec déjeuner (BBQ)', 'Profitez d’une excursion exclusive et privée en speedboat au départ de Grand Baie vers l’Île Plate, l’Île aux Gabriel et le Coin de Mire. Naviguez à votre propre rythme, découvrez des lagons aux eaux cristallines, faites du snorkeling dans une mer foisonnante de vie marine et détendez-vous sur des plages immaculées. Votre expérience comprend un délicieux déjeuner BBQ servi sur l’île, ainsi qu’une sélection de boissons rafraîchissantes tout au long de la journée. Idéal pour les couples, les familles ou les petits groupes en quête d’une aventure insulaire personnalisée.', 'Profitez d’une excursion exclusive et privée en speedboat à la découverte de trois îles du Nord de Maurice. Au départ de Grand Baie, vous naviguerez pendant environ 45 minutes jusqu’à l’Île Plate, où vous pourrez vous détendre sur la plage, nager dans des eaux cristallines ou faire du snorkeling dans de magnifiques lagons.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('ef964850-098a-4876-a1c0-c76e350eb54f', '83ec6f71-6e52-4406-ad53-74ab45d1bd21', 'fr'::content_locale, 'Tour privé d’une journée complète aux 5 îles – Île aux Cerfs avec déjeuner', 'Profitez d’une excursion privée en speedboat, d’une journée complète, au départ de Trou d’Eau Douce : visite de la cascade GRSE, snorkeling parmi de superbes jardins de corail, découverte des cinq îles, déjeuner BBQ savoureux et détente sur les magnifiques plages du nord de l’Île aux Cerfs.', 'Embarquez pour une excursion privée en speedboat au départ de Trou d’Eau Douce, pour une journée complète d’aventure et de détente.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('e918e254-616f-4a41-9895-4def4e5b7039', '8b2bff90-c935-424a-871a-a7d0b3047ca1', 'fr'::content_locale, 'Nage privée avec les dauphins uniquement', 'Profitez d’une excursion matinale exclusive en speedboat vers la baie de Tamarin pour nager avec des dauphins sauvages dans leur habitat naturel, suivie d’une séance de snorkeling au-dessus de récifs coralliens éclatants de couleurs. Cette excursion privée offre une expérience plus personnalisée et flexible, à votre propre rythme.', 'Rendez votre séjour à Maurice véritablement inoubliable grâce à une expérience privée et exclusive de nage avec les dauphins. Embarquez tôt, à 7 h 30, à bord de votre speedboat privé, en direction de la baie de Tamarin, où vous rencontrerez des dauphins sauvages dans leur habitat naturel. Profitez de la liberté d’une excursion personnalisée, à votre propre rythme, en glissant dans des eaux cristallines pour observer ces créatures magnifiques de près. Écoutez leurs cris, admirez leurs mouvements gracieux et vivez un lien extraordinaire avec la nature, dans un cadre paisible et préservé de la foule.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('a10bd721-0bdd-4cdf-a381-7cadd221b18c', '8d143960-f55b-4658-9a9d-d798726207f0', 'fr'::content_locale, 'Croisière privée en catamaran d’une journée complète – Côte Ouest', 'Profitez d’une croisière privée en catamaran vers la baie de Tamarin, à la recherche des dauphins dans leur habitat naturel, avec du snorkeling près d’un magnifique récif corallien et un délicieux déjeuner à l’ancre, aux abords de l’emblématique Crystal Rock.', 'Embarquez à bord de votre catamaran privé en direction de la baie de Tamarin, à la recherche des dauphins dans leur habitat naturel, pour une expérience magique et inoubliable au contact de la faune sauvage. Faites ensuite une halte près d’un magnifique récif corallien pour du snorkeling dans des eaux cristallines et découvrez la vie marine foisonnante sous la surface. Savourez un délicieux déjeuner servi à bord, à l’ancre près de l’emblématique Crystal Rock, entouré des paysages à couper le souffle de Maurice.', '{"Départ de Rivière Noire (région Ouest)","Observation des dauphins dans la baie de Tamarin","Snorkeling à Crystal Rock (région Ouest)","Île aux Bénitiers (région Ouest)","Déjeuner à bord (région Ouest)"}'::text[], '{"Déjeuner à bord : salades","Pain au beurre à l’ail","Poulet, poisson, saucisse","Eau, Coca, bière, vin, rhum local","Banane flambée","Salades de fruits",Snorkeling}'::text[], '{"Merci de ne pas boire d’alcool si vous devez conduire !","Arrivez au point d’embarquement au moins 15 minutes avant le départ","Les personnes venant par leurs propres moyens doivent se référer à Google Maps pour l’itinéraire"}'::text[], 'Rivière Noire', NULL, NULL, 'machine', E'{"itinerary": [{"tags": [], "title": "Black River", "description": "Départ"}, {"tags": [], "title": "Tamarin", "description": "Coin secret\\nObservation des dauphins"}, {"tags": [], "title": "Crystal Rock, Tamarin", "description": "Snorkeling"}, {"tags": [], "title": "Benitier Island", "description": "Déjeuner à bord"}], "whatToBring": ["Chaussures confortables", "Lunettes de soleil", "Chapeau", "Maillot de bain", "Vêtements de rechange", "Serviette", "Appareil photo", "Crème solaire", "Équipement de snorkeling"], "importantInfo": ["Les bébés de 1 à 4 ans voyagent gratuitement.", "Tous les repas sont halal. Les repas végétariens doivent être demandés à l’avance.", "La prise en charge et le retour sont disponibles si l’option correspondante est sélectionnée.", "Un parking public est disponible à 60 m du point de rendez-vous. Merci d’arriver tôt pour être sûr d’avoir une place. Contactez notre équipe sur WhatsApp pour l’emplacement.", "L’itinéraire peut être modifié en raison de la météo, de l’état de la mer, des marées ou de contraintes opérationnelles pour la sécurité des passagers.", "Les décisions du capitaine concernant la navigation, les horaires et les modifications de l’itinéraire sont définitives et prises dans l’intérêt de la sécurité des passagers.", "Les passagers en fauteuil roulant doivent se tenir debout brièvement pour monter à bord de la navette et en descendre, avec l’aide de notre équipage, afin d’accéder au catamaran.", "Pour leur confort et leur sécurité, les passagers sont invités à garder leurs effets personnels avec eux à tout moment. La société ne pourra être tenue responsable de toute perte, vol, dommage ou égarement d’objets personnels pendant l’excursion."]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('6ebfb964-28e3-4b63-b62b-668a9fbdc155', '9962c783-f94a-41b3-bc9f-db2980aefe6b', 'fr'::content_locale, 'Croisière en catamaran – Aventure des 3 îles du Nord', 'Une journée complète au départ de Grand Baie à la découverte de l’Île Plate, avec snorkeling dans le lagon, un déjeuner gastronomique à bord, une pause détente à l’Île aux Gabriel et une vue sur le coucher de soleil au Coin de Mire.', 'Partez de Grand Baie pour une journée complète à la découverte de l’Île Plate. Profitez d’une séance de snorkeling dans un lagon aux eaux cristallines, peuplé d’une incroyable variété de poissons et de coraux. Un déjeuner gastronomique est préparé à bord du spacieux catamaran, suivi d’un moment de détente à l’Île aux Gabriel. La journée se termine par une vue sur le coucher de soleil sur les falaises spectaculaires du Coin de Mire.', '{"Île Plate (région Nord)","Île aux Gabriel (région Nord)","Coin de Mire (région Nord)","Snorkeling (région Nord)"}'::text[], '{"Déjeuner avec salades","Pain au beurre à l’ail","Poulet/poisson/saucisse grillés","Eau, Coca, bière, vin, rhum local","Banane flambée","Salades de fruits",Snorkeling}'::text[], '{"Ne buvez pas d’alcool si vous devez conduire","Arrivez 15 minutes avant le départ","Les personnes venant par leurs propres moyens doivent se référer à Google Maps pour l’itinéraire"}'::text[], 'Grand Baie', NULL, NULL, 'human', '{"itinerary": [{"tags": [], "title": "Grand Baie, Sunset Boulevard", "description": "Départ"}, {"tags": [], "title": "Gabriel Island", "description": "Visite"}, {"tags": [], "title": "Flat Island", "description": null}, {"tags": [], "title": "Gunner''s Quoin", "description": "Snorkeling"}]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('1fb0b03d-a74f-4ca1-be01-2811f856af98', 'a23001d8-f1a1-407e-9ab3-7075f4ff14ac', 'fr'::content_locale, 'Vallée Adventure Park', 'Excursion d’une journée au parc naturel de La Vallée des Couleurs, avec sa terre aux 23 couleurs, ses quatre cascades, sa faune et sa flore indigènes, dans le sud de Maurice.', 'Ce site séduira les amoureux de la nature, offrant une expérience unique au cœur d’une faune et d’une flore indigènes. Le parc présente des paysages variés : plateaux, montagnes, vallées, cratères et lacs de cratère.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('d38e6a03-a52d-4646-9d0a-04bf811d38fa', 'a9164fa6-a19b-4789-866f-0f967dcde449', 'en'::content_locale, 'North Tour – Port Louis, Pamplemousses & Cap Malheureux', 'Guided day tour of the north: the capital Port Louis, the Pamplemousses botanical garden and Cap Malheureux.', NULL, '{}'::text[], '{}'::text[], '{}'::text[], NULL, NULL, NULL, 'human', NULL::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('ec2c912a-948e-4b5e-88f7-5b4aca0207f4', 'a9164fa6-a19b-4789-866f-0f967dcde449', 'fr'::content_locale, 'Circuit privé dans le Nord de l''île Maurice', 'Circuit privé d’une journée dans le Nord de l’île Maurice avec chauffeur-guide : découvrez Port-Louis et son marché central, le jardin botanique de Pamplemousses, Grand Baie et l’emblématique église au toit rouge de Cap Malheureux.', 'Découvrez la beauté, la culture et l’histoire du Nord de l’île Maurice lors de ce circuit privé d’une journée. Voyagez dans le confort avec un chauffeur-guide local expérimenté et explorez certains des sites les plus emblématiques de l’île.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('61239daa-e31d-470e-82d8-7406a7554aa3', 'bedf9528-77e9-4f62-9be3-f0726f38ea40', 'fr'::content_locale, NULL, NULL, NULL, '{}'::text[], '{}'::text[], '{}'::text[], NULL, NULL, NULL, 'human', NULL::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('aad3a35f-1ec8-4bf0-93c5-4ea824de2bd4', 'bfb6c5df-ccdc-4090-bd86-a1b7491c35b6', 'fr'::content_locale, 'Journée complète en speedboat aux 3 îles du Nord avec déjeuner (BBQ)', 'Une excursion privée d’une journée en speedboat au départ de Grand Baie vers l’Île Plate, l’Île aux Gabriel et le Coin de Mire, avec snorkeling, déjeuner BBQ et boissons.', 'Une excursion privée d’une journée en speedboat pour visiter trois îles du Nord de Maurice. Le départ se fait de Grand Baie, avec un trajet d’environ 45 minutes jusqu’à l’Île Plate, pour un moment de détente et de snorkeling dans les lagons.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('ed3b410a-c0f6-450b-9d59-13b6fb2a3a7b', 'c0d11d15-ab7a-4ca0-9085-0af44c6ade2a', 'fr'::content_locale, 'Tour d’une journée complète aux 5 îles – Île aux Cerfs avec déjeuner', 'Une excursion en speedboat d’une journée complète au départ de Trou d’Eau Douce : la cascade GRSE, du snorkeling parmi les jardins de corail, cinq îles, un déjeuner BBQ et les plages du nord de l’Île aux Cerfs.', 'Cette excursion en speedboat au départ de Trou d’Eau Douce promet une évasion totale.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('b0464cca-7354-4269-8adb-86dbaa07c341', 'c82ee24e-5841-4d0f-93f2-18b226638317', 'fr'::content_locale, 'Croisière en catamaran – Côte Ouest', 'Direction la baie de Tamarin à la recherche des dauphins dans leur habitat naturel, avec du snorkeling près d’un récif corallien et un déjeuner à l’ancre, aux abords de Crystal Rock.', 'Direction la baie de Tamarin à la recherche des dauphins dans leur habitat naturel, pour une expérience magique et inoubliable d’observation de ces créatures majestueuses en fin de matinée. La croisière comprend une halte près d’un magnifique récif corallien pour une séance de snorkeling dans des eaux cristallines, à la découverte de l’incroyable beauté et diversité de la vie sous-marine. Un délicieux déjeuner est servi à l’ancre, avec vue sur Crystal Rock scintillant sous le soleil tropical.', '{"Départ de Rivière Noire (région Ouest)","Observation des dauphins dans la baie de Tamarin","Snorkeling à Crystal Rock (région Ouest)","Île aux Bénitiers (région Ouest)","Déjeuner à bord (région Ouest)"}'::text[], '{"Déjeuner à bord : salades","Pain au beurre à l’ail","Poulet, poisson, saucisse","Eau, Coca, bière, vin, rhum local","Banane flambée","Salades de fruits",Snorkeling}'::text[], '{"Merci de ne pas boire d’alcool si vous devez conduire !","Arrivez au point d’embarquement au moins 15 minutes avant le départ","Les personnes venant par leurs propres moyens doivent se référer à Google Maps pour l’itinéraire"}'::text[], NULL, NULL, NULL, 'human', '{"itinerary": [{"tags": [], "title": "Black River", "description": "Départ"}, {"area": "Coin secret", "tags": [], "title": "Tamarin", "description": "Observation des dauphins"}, {"tags": [], "title": "Crystal Rock, Tamarin", "description": "Snorkeling"}, {"tags": [], "title": "Benitier Island", "description": "Déjeuner à bord"}]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('ed9a4f93-5d3b-4da9-9c8a-4339e55ca543', 'ca8a0ff4-e24d-4712-ac91-457ee60d6c04', 'fr'::content_locale, 'Catamaran privé d’une journée complète – Île aux Cerfs', 'Embarquez pour une croisière privée en catamaran d’une journée complète au départ de Trou d’Eau Douce, pour une journée inoubliable avec la visite de la cascade de la Grande Rivière Sud-Est, du snorkeling dans des lagons turquoise, un déjeuner BBQ gastronomique à bord et une halte détente à l’idyllique Île aux Cerfs.', 'Profitez d’une croisière privée exclusive en catamaran d’une journée complète, au départ de Trou d’Eau Douce, sur la côte Est de Maurice. Naviguez jusqu’à la spectaculaire cascade de la Grande Rivière Sud-Est, faites du snorkeling dans des eaux cristallines et savourez un délicieux déjeuner BBQ avec boissons servi à bord. Poursuivez vers l’idyllique Île aux Cerfs, où vous pourrez vous détendre sur des plages de sable blanc immaculées, nager dans le lagon turquoise et profiter à votre rythme de la beauté de ce paradis tropical.', '{"Île aux Cerfs (région Est)","Cascade GRSE (région Est)","Snorkeling (Eau Bleue)","Déjeuner BBQ et boissons à bord"}'::text[], '{"Salades et pain au beurre à l’ail","BBQ : poulet, poisson, saucisse","Boissons : eau, Coca, bière, vin, rhum local","Dessert : banane flambée",Snorkeling}'::text[], '{"Activités nautiques (parachute ascensionnel, etc.)"}'::text[], 'Route Royale Maho, Trou d’Eau Douce', NULL, NULL, 'human', '{"itinerary": [{"tags": [], "title": "Route Royale Maho, Trou d''Eau Douce", "description": "Départ"}, {"tags": [], "title": "Grand River South East Waterfall", "description": "Visite touristique"}, {"tags": [], "title": "Ile aux cerfs", "description": "Snorkeling + déjeuner BBQ et boissons à bord"}, {"tags": [], "title": "Ile aux cerfs", "description": "Baignade et détente"}], "whatToBring": ["Chaussures confortables", "Lunettes de soleil", "Chapeau", "Maillot de bain", "Vêtements de rechange", "Serviette", "Appareil photo", "Crème solaire", "Équipement de snorkeling"], "importantInfo": ["Arrivez au point d’embarquement au moins 15 minutes avant le début de la croisière", "Les passagers utilisant leur propre véhicule ne doivent pas boire d’alcool s’ils conduisent", "Tous les repas sont halal. Les repas végétariens doivent être demandés à l’avance.", "La prise en charge et le retour sont disponibles si l’option correspondante est sélectionnée.", "Un parking public est disponible à 60 m du point de rendez-vous. Merci d’arriver tôt pour être sûr d’avoir une place. Contactez notre équipe sur WhatsApp pour plus d’informations.", "L’itinéraire peut être modifié en raison de la météo, de l’état de la mer, des marées ou de contraintes opérationnelles pour la sécurité des passagers.", "Les décisions du capitaine concernant la navigation, les horaires et les modifications de l’itinéraire sont définitives et prises dans l’intérêt de la sécurité des passagers.", "Les passagers en fauteuil roulant doivent se tenir debout brièvement pour monter à bord de la navette et en descendre, avec l’aide de notre équipage, afin d’accéder au catamaran.", "Pour leur confort et leur sécurité, les passagers sont invités à garder leurs effets personnels avec eux à tout moment. La société ne pourra être tenue responsable de toute perte, vol, dommage ou égarement d’objets personnels pendant l’excursion."]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('5190503e-7add-401e-b566-b269d1f67335', 'd29e7a9e-9197-4c05-afcc-ad9f370668c5', 'fr'::content_locale, 'Nage avec les dauphins uniquement', 'Excursion matinale en speedboat vers la baie de Tamarin pour nager avec des dauphins sauvages dans leur habitat naturel, suivie d’une séance de snorkeling au-dessus de récifs coralliens.', 'Rendez votre séjour à Maurice véritablement inoubliable grâce à l’expérience magique de la nage avec les dauphins. Embarquez tôt, à 7 h 30, à bord d’un speedboat, en direction de la baie de Tamarin, où vous rencontrerez ces créatures extraordinaires dans leur habitat naturel. Ressentez le frisson de plonger dans des eaux cristallines et d’observer les dauphins jouer à quelques mètres de vous. Écoutez leurs cris, observez leurs mouvements gracieux et profitez d’un moment unique de connexion avec la nature. Cette aventure extraordinaire vous comblera de joie, d’émerveillement et d’un sentiment de liberté inégalé.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('b5b417b4-aadd-4879-9812-a3f5de825eb9', 'd4dcc848-ef41-4f8f-85db-14bbd3803a2c', 'fr'::content_locale, 'Randonnée aux Tamarind Falls / 7 Cascades', 'Randonnée guidée jusqu’aux Tamarind Falls (7 Cascades), la plus haute chute d’eau de Maurice, à travers des plateaux riches en plantes et en oiseaux exotiques.', 'Les 7 Cascades, également connues sous le nom de Tamarind Falls, se situent près du petit village de Henrietta, sur les hauts plateaux de Maurice, et prennent leur source dans la Rivière Tamarin. Les 7 Cascades mesurent 293 mètres (961 pieds), ce qui en fait la plus haute chute d’eau de Maurice.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('2ffa94c0-769e-4dfb-bbf7-fa75446bafd6', 'da49a019-deca-40cf-9de8-d146e24261de', 'fr'::content_locale, 'Transfert aéroport', 'Transfert privé avec accueil personnalisé entre l’aéroport international SSR et votre lieu d’hébergement, 24 h/24 et 7 j/7.', NULL, '{"Accueil personnalisé","24 h/24 et 7 j/7","Porte à porte"}'::text[], '{Chauffeur,"Aide aux bagages"}'::text[], '{}'::text[], 'Aéroport international SSR (arrivées)', NULL, NULL, 'machine', NULL::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('d9021ef7-c280-46dd-8df9-edd1d56bc7b8', 'dcac8588-b2f3-4802-959f-970d1aa88755', 'fr'::content_locale, 'Aventure privée d’une journée complète aux 3 îles du Nord', 'Profitez d’une croisière privée d’une journée complète en catamaran au départ de Grand Baie vers l’Île Plate, avec snorkeling dans le lagon, un déjeuner gastronomique servi à bord, un moment de détente à l’Île aux Gabriel et des vues à couper le souffle sur le Coin de Mire.', 'Partez de Grand Baie à bord de votre catamaran privé pour une croisière d’une journée complète vers l’Île Plate. Faites du snorkeling dans le lagon aux eaux cristallines, abritant de superbes récifs coralliens et une grande variété de poissons tropicaux. Savourez un délicieux déjeuner gastronomique servi à bord en naviguant à travers les eaux turquoise éblouissantes. Détendez-vous sur la plage immaculée de l’Île aux Gabriel ou profitez du spacieux catamaran à votre propre rythme. Terminez votre journée inoubliable par une vue à couper le souffle sur les falaises spectaculaires du Coin de Mire, avant de rentrer à Grand Baie.', '{"Île Plate (région Nord)","Île aux Gabriel (région Nord)","Coin de Mire (région Nord)","Snorkeling (région Nord)"}'::text[], '{"Déjeuner avec salades","Pain au beurre à l’ail","Poulet/poisson/saucisse grillés","Eau, Coca, bière, vin, rhum local","Banane flambée","Salades de fruits",Snorkeling}'::text[], '{"Ne buvez pas d’alcool si vous devez conduire","Arrivez 15 minutes avant le départ","Les personnes venant par leurs propres moyens doivent se référer à Google Maps pour l’itinéraire"}'::text[], 'Grand Baie', NULL, NULL, 'machine', '{"itinerary": [{"tags": [], "title": "Grand Baie, Sunset Boulevard", "description": "Départ"}, {"tags": [], "title": "Gunner''s Quoin", "description": "Snorkeling"}, {"tags": [], "title": "Gabriel Island", "description": "Visite"}, {"tags": [], "title": "Flat Island", "description": "Visite touristique"}], "whatToBring": ["Chaussures confortables", "Lunettes de soleil", "Chapeau", "Maillot de bain", "Vêtements de rechange", "Serviette", "Appareil photo", "Crème solaire", "Équipement de snorkeling"], "importantInfo": ["Les bébés de 1 à 4 ans voyagent gratuitement.", "Tous les repas sont halal. Les repas végétariens doivent être demandés à l’avance.", "La prise en charge et le retour sont disponibles si l’option correspondante est sélectionnée.", "Un parking public est disponible à 60 m du point de rendez-vous. Merci d’arriver tôt pour être sûr d’avoir une place. Contactez notre équipe sur WhatsApp pour l’emplacement.", "L’itinéraire peut être modifié en raison de la météo, de l’état de la mer, des marées ou de contraintes opérationnelles pour la sécurité des passagers.", "Les décisions du capitaine concernant la navigation, les horaires et les modifications de l’itinéraire sont définitives et prises dans l’intérêt de la sécurité des passagers.", "Les passagers en fauteuil roulant doivent se tenir debout brièvement pour monter à bord de la navette et en descendre, avec l’aide de notre équipage, afin d’accéder au catamaran.", "Pour leur confort et leur sécurité, les passagers sont invités à garder leurs effets personnels avec eux à tout moment. La société ne pourra être tenue responsable de toute perte, vol, dommage ou égarement d’objets personnels pendant l’excursion."]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('19911d91-1114-42e4-b872-aabe2902b1e5', 'dcad49d8-35c3-4454-a6e6-cf96743b32b9', 'fr'::content_locale, 'Excursion de marche sous-marine', 'Marchez sur le fond marin à une profondeur de 10 à 13 pieds, en combinaison de plongée, accompagné d’instructeurs expérimentés, pour observer la faune et la flore marines.', 'Équipé d’une combinaison de plongée et accompagné d’instructeurs expérimentés, plongez dans le monde sous-marin à une profondeur de 10 à 13 pieds pour une expérience inoubliable et enrichissante.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('7d79bdc6-fc57-4459-a1df-53e107b43397', 'e0a2004b-4f7a-46a2-95f7-c7866c4980c9', 'fr'::content_locale, 'Survolez la cascade sous-marine – Tour en hydravion à Maurice', 'Décollez pieds nus depuis le lagon turquoise de la plage de La Prairie et survolez la célèbre illusion de cascade sous-marine, aux abords d’un site classé au patrimoine mondial de l’UNESCO.', 'Nous avons le privilège de survoler chaque jour la cascade sous-marine. Nos hydravions décollent depuis la plage de La Prairie, juste à côté de cette merveille naturelle. À quelques pas de là, pieds nus dans le lagon turquoise, vous embarquez à bord de l’hydravion. Préparez-vous à décoller depuis des eaux cristallines, aux abords d’un site classé au patrimoine mondial de l’UNESCO. Confortablement installé aux côtés du pilote, vous découvrirez cette célèbre illusion : une cascade au fond de l’océan Indien. C’est magique et majestueux. Cette vue, l’une des plus photogéniques au monde, a captivé la planète entière depuis que ses photos ont fait le tour d’internet. Ce trésor naturel se doit vraiment d’être vu de ses propres yeux.', '{"Survolez la célèbre illusion de cascade sous-marine, au fond de l’océan Indien","Décollez pieds nus depuis le lagon turquoise de la plage de La Prairie","Installé aux côtés du pilote","Vue sur un site classé au patrimoine mondial de l’UNESCO","Trois formules : 15 min (le court « Ambre »), 30 min (l’expérience Turquoise), 60 min (le mythique Est)"}'::text[], '{}'::text[], '{}'::text[], NULL, NULL, NULL, 'machine', '{"importantInfo": ["Merci d’arriver au point d’embarquement au moins 15 minutes avant l’heure de départ prévue.", "L’itinéraire vers le point d’embarquement est disponible sur Google Maps.", "Merci de ne pas boire d’alcool si vous devez conduire !", "Prise en charge et retour disponibles partout sur l’île.", "Frais d’annulation de 50 % pour toute annulation dans les 24 heures précédant l’excursion.", "Frais d’annulation de 100 % pour toute annulation le jour de l’excursion.", "Si l’annulation est faite par Belle Mare Tours Ltd, un remboursement intégral sera effectué par virement bancaire sur le compte du client.", "Modes de paiement : le paiement peut être effectué en espèces auprès du chauffeur en MUR, EUR ou USD, ou en ligne avant votre excursion."]}'::jsonb, NULL);
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('42c31930-9783-45aa-bba1-e76e677e5612', 'f286759a-7721-4414-b8fd-dc164eb3120c', 'fr'::content_locale, 'Excursion shopping privée', 'Journée complète ou demi-journée : faire du shopping à Maurice peut être une expérience merveilleuse. L’artisanat traditionnel, ainsi que les plus beaux produits de luxe, se trouvent dans divers centres commerciaux et boutiques.', 'Journée complète ou demi-journée : faire du shopping à Maurice peut être une expérience merveilleuse. L’artisanat traditionnel, ainsi que les plus beaux produits de luxe, se trouvent dans divers centres commerciaux et boutiques.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('8c1495a9-7be6-4e13-b346-95ef6a0da546', 'f328f009-1ab5-442b-ab0a-90d052ffe3eb', 'fr'::content_locale, 'Journée nage avec les dauphins à l’Île aux Bénitiers avec déjeuner', 'Excursion en speedboat d’une journée complète dans l’Ouest de Maurice : nagez avec les dauphins, faites du snorkeling, visitez Crystal Rock et savourez un déjeuner barbecue à l’Île aux Bénitiers.', 'Cette excursion en speedboat d’une journée complète offre une immersion totale dans l’océan, dans la région Ouest de Maurice.
insert into activity_translations ("id", "activity_id", "locale", "title", "summary", "description", "highlights", "inclusions", "exclusions", "meeting_point", "seo_title", "seo_description", "source", "extra", "supplement_name") values ('35a84fd5-7240-4979-804f-ad7f0b3d06eb', 'fb842149-9737-469b-a116-4b2b25230456', 'fr'::content_locale, 'Circuit privé dans le Sud-Est de l’île Maurice', 'Explorez le Sud-Est de l’île Maurice et laissez-vous séduire par sa riche histoire, son patrimoine culturel fascinant et ses trésors cachés au cœur de paysages enchanteurs.', 'Découvrez les merveilles du Sud-Est de l’île Maurice lors de ce circuit privé, une expérience captivante mêlant histoire, culture et paysages d’exception.
